public static int removeElement(int[] nums, int val) {
    int j = 0;
    Stack<Integer> stk = new Stack<>();

    for (int i = 0; i < nums.length; i++){
        if (nums[i] != val){
            nums[j] = nums[i];
            stk.push(nums[i]);
            j++;
        }
    }

    return stk.size();
}
